with sync_playwright() as p:
 b=p.chromium.launch();g=b.new_page();g.add_init_script("""window.audioProbe={osc:0,buffer:0};const os=AudioContext.prototype.createOscillator,bs=AudioContext.prototype.createBufferSource;AudioContext.prototype.createOscillator=function(){audioProbe.osc++;return os.call(this)};AudioContext.prototype.createBufferSource=function(){audioProbe.buffer++;return bs.call(this)}""");g.goto('http://localhost:8080/');g.evaluate("""async()=>{let m=await import('/habit-shifts.js?v=2');window.game=m.mountHabit(document.querySelector('#app'),{mode:'magazine',seed:0,onExit:()=>{},onFinish:()=>{}});document.querySelector('#habitStart').click()}""");box=g.locator('#habitCanvas').bounding_box();g.mouse.click(box['x']+box['width']*6.5/27,box['y']+box['height']*3.5/17);assert g.evaluate('audioProbe.buffer')>0,'shot must generate noise';g.click('#habitMusic');assert g.evaluate('audioProbe.osc')>=4,'music must schedule chord and bass oscillators';assert g.evaluate("document.querySelector('#habitMusic').dataset.audioState")=='running';print('PASS real shot node and running music oscillators',g.evaluate('audioProbe'));b.close()
